bool ReportParameters::validateJsonForCreation(const Json::Value &pJson, std::string &err)
{
    if(pJson.isMember("id"))
    {
        if(!validJsonOfField(0, "id", pJson["id"], err, true))
            return false;
    }
    if(pJson.isMember("report_id"))
    {
        if(!validJsonOfField(1, "report_id", pJson["report_id"], err, true))
            return false;
    }
    else
    {
        err="The report_id column cannot be null";
        return false;
    }
    if(pJson.isMember("parameter_name"))
    {
        if(!validJsonOfField(2, "parameter_name", pJson["parameter_name"], err, true))
            return false;
    }
    else
    {
        err="The parameter_name column cannot be null";
        return false;
    }
    if(pJson.isMember("parameter_label"))
    {
        if(!validJsonOfField(3, "parameter_label", pJson["parameter_label"], err, true))
            return false;
    }
    else
    {
        err="The parameter_label column cannot be null";
        return false;
    }
    if(pJson.isMember("parameter_type"))
    {
        if(!validJsonOfField(4, "parameter_type", pJson["parameter_type"], err, true))
            return false;
    }
    if(pJson.isMember("is_mandatory"))
    {
        if(!validJsonOfField(5, "is_mandatory", pJson["is_mandatory"], err, true))
            return false;
    }
    if(pJson.isMember("default_value"))
    {
        if(!validJsonOfField(6, "default_value", pJson["default_value"], err, true))
            return false;
    }
    if(pJson.isMember("display_order"))
    {
        if(!validJsonOfField(7, "display_order", pJson["display_order"], err, true))
            return false;
    }
    return true;
}
